/* Check the set of overloadings in this compilation unit:
 *
 * For every trait and object, check dotted methods and functional methods, taking inheritance into account
 * Check top-level functions, taking functional methods and top-level variables into account
 * Check local functions, taking local variables into account
 *
 * The following features are not (fully) checked yet:
 *     static parameters
 *     exclusion relationships
 *     varargs parameters
 *     keyword parameters
 */
class OverloadingChecker(compilation_unit: CompilationUnitIndex,
                         globalEnv: GlobalEnvironment) {
    var typeAnalyzer = TypeAnalyzer.make(new TraitTable(compilation_unit, globalEnv))
    val globalOracle = new OverloadingOracle()(typeAnalyzer)
    var errors = List[StaticError]()

    private final val cacheOverloadChecks = ProjectProperties.getBoolean("fortress.analyzer.overload.cache", true)

    private def getFunctionsFromCompilationUnit(index: CompilationUnitIndex,
                                                f: IdOrOpOrAnonymousName)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      getFunctions(index, f, compilation_unit.isInstanceOf[ComponentIndex])

    private def getFunctions(index: CompilationUnitIndex,
                             f: IdOrOpOrAnonymousName)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      getFunctions(index, f, false)

    private def getFunctions(index: CompilationUnitIndex,
                             f: IdOrOpOrAnonymousName,
                             onlyConcrete: Boolean)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
      val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
      val fns = toFunctionArrows(fndecls, onlyConcrete)
      if ( index.variables.keySet.contains(f) )
        index.variables.get(f) match {
          case SDeclaredVariable(lvalue)
               if lvalue.getIdType.unwrap.isInstanceOf[ArrowType] =>
            fns :+ ((lvalue.getIdType.unwrap.asInstanceOf[ArrowType], None, None))
          case _ => fns
        }
      else fns
    }

    private def getFunctionalMethods(index: CompilationUnitIndex, f: IdOrOpOrAnonymousName): List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
        val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
        val fndeclsfiltered = fndecls.filter(f => f.isInstanceOf[JavaFunctionalMethod])
        toFunctionArrows(fndeclsfiltered, false)
    }

    private def getDeclaredFunctions(index: CompilationUnitIndex, f: IdOrOpOrAnonymousName): List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
        val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
        val fndeclsfiltered = fndecls.filter(f => f.isInstanceOf[DeclaredFunction])
        toFunctionArrows(fndeclsfiltered, false)
    }    

    // in a component (onlyConcrete), the functions with a body and every functional method,
    // abstract ones included, as the Meet Rule for functions judges one beside a function;
    // but an abstract one implemented by a declaration of a subtype with the same parameter
    // types, as toFunctionalMethodArrows reads them
    private def toFunctionArrows(set: Set[JavaFunctional], onlyConcrete: Boolean):
        List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
      val arrows = set.filter(s => isFunction(s) &&
                      (!onlyConcrete || isFunctionalMethod(s) || s.asInstanceOf[JavaFunctional].body.isSome))
         .toList.map(f => (selfTyped(NF.makeArrowType(f.getSpan,
				     paramsToType(f.parameters, f.getSpan),
				     f.getReturnType.unwrap,
				     getStaticParameters(f, true)), f,
.....
     * since it must be a subtype of the static argument that it gives. For a functional
     * method of such a trait, parameters() keeps self at the plain trait type, which
     * specificity, the Meet Rule, the coverage rule and the Return Type Rule read; the
     * declaration's own parameters (FunctionalMethod.ast) keep its TraitSelfType. An arrow
     * made from those by the same steps as the plain arrow is kept beside it, keyed by the
     * plain arrow's identity, and validOverloadingInner's exclusion test reads it. */
    private val exclusionArrows = new java.util.IdentityHashMap[ArrowType, ArrowType]()
    private def selfTyped(a: ArrowType, f: JavaFunctional, mk: JavaList[Param] => ArrowType): ArrowType = {
      f match {
        case fm: JavaFunctionalMethod =>
          val own = NU.getParams(fm.ast)
          if (!own.equals(fm.parameters)) exclusionArrows.put(a, mk(own))
        case _ =>
      }
      a
    }
    private def forExclusion(a: ArrowType): ArrowType = {
      val e = exclusionArrows.get(a)
      if (e == null) a else e
    }
    private val validOverloadingMemo = new scala.collection.mutable.HashMap[
        (ArrowType, Option[Int], ArrowType, Option[Int], Set[(ArrowType, Option[Int])], Boolean, List[StaticParam]), Boolean]()

    private def validOverloading(first: (ArrowType,Option[Int],Option[JavaFunctional]),
				 second: (ArrowType,Option[Int],Option[JavaFunctional]),
				 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				 isMethod: Boolean,
				 oa: OverloadingOracle,
				 debug:Boolean=false): Boolean = {
        val fnal1 = first._3
        val fnal2 = second._3
        if (cacheOverloadChecks && !fnal1.isEmpty && !fnal2.isEmpty) {
            val key = (first._1, first._2, second._1, second._2,
                       signatures.map(s => (s._1, s._2)).toSet, isMethod, staticParamsInScope)
            val cv = validOverloadingMemo.get(key)
            if (!cv.isEmpty && cv.get)
	        true
	    else {
                val result = validOverloadingInner(first, second, signatures, isMethod, oa, debug)
                if (result) validOverloadingMemo += (key -> result)
                result
            }
        } else validOverloadingInner(first, second, signatures, isMethod, oa, debug)
    }

    /* Checks the overloading rules: subtype / exclusion / meet */
    private def validOverloadingInner(first: (ArrowType,Option[Int],Option[JavaFunctional]),
				      second: (ArrowType,Option[Int],Option[JavaFunctional]),
				      signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				      isMethod: Boolean,
				      oa: OverloadingOracle,
				      debug:Boolean=false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      true

      // the one test that reads no type, first
      if (functionalMethodsAtOnePosition(first, second, isMethod)) { true }
      else if (oa.lteq(fa, ga)) { true }
      else if (oa.lteq(ga, fa)) { true }
      else if (meetRule(first, second, signatures, isMethod, oa, debug)) { true }
      else if (oa.excludes(forExclusion(fa), forExclusion(ga))) { true }
      else { coverageRule(first, second, signatures, isMethod, oa) }


  /*    
      println("Specificity\n")
      val b1 = oa.lteq(fa, ga)
      if (b1) true 
      val b2 = oa.lteq(ga, fa) 
      if (b2) return true
      println("Meet Rule\n")
      val b3 = meetRule(first, second, signatures, isMethod, oa, debug)
      if (b3) return true
      println("Exclusion\n")
      val b4 = oa.excludes(fa, ga) 
      println("Done")
      return b4
  */

      //if (b1) !b2 else ( b2 || b3 || b4 )  //JT: It looks like the duplicate rule IS enforced somewhere else
      //(b1 || b2 || b3 || b4)
    }

    /* The Meet Rule for Functional Methods: two functional methods with their self
     * parameters at one position are a valid overloading among the top-level functionals;
     * the meet the rule asks of a trait or object that provides both is checked for that
     * trait or object (checkOverloading's loop over them). */
    private def functionalMethodsAtOnePosition(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               second: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               isMethod: Boolean): Boolean =
      !isMethod && first._2.isDefined && first._2 == second._2 &&
      first._3.exists(isFunctionalMethod) && second._3.exists(isFunctionalMethod)

    private def meetRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
    	                 second: (ArrowType,Option[Int],Option[JavaFunctional]),
			 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			 isMethod: Boolean,
			 oa: OverloadingOracle,
			 debug : Boolean = false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      val b1 = fsp == gsp
      val b2 = (fsp == gsp) &&
      signatures.exists(third => third match {
           case (ha, hsp, _) => {
              val a1 = (hsp == fsp) 
              val a2 = a1 && oa.lteq(ha, fa) 
              val a3 = a2 && oa.lteq(ha, ga) 
              val a4 = a3 && (if (isMethod && fsp.isDefined)
                                oa.isMeet(withoutSelf(ha, fsp.get), withoutSelf(fa, fsp.get), withoutSelf(ga, fsp.get), false, debug)
                              else oa.isMeet(ha, fa, ga, isMethod, debug))
     //         if (debug)
     //             println("" + ha + " " + a1 + a2 + a3 + a4)

              a4}})
      b2
    }

    // the self parameter of a functional method is compared as a dotted method's receiver is, wherever it sits
    private def withoutSelf(a: ArrowType, i: Int): ArrowType = {
      val d = a.getDomain match {
        case t: TupleType =>
          NF.makeTupleType(NU.getSpan(t), toJavaList(toListFromImmutable(t.getElements).zipWithIndex.filter(_._2 != i).map(_._1)))
        case t => NF.makeTupleType(NU.getSpan(t), toJavaList(List[Type]()))
      }
      NF.makeArrowType(NU.getSpan(a), d, a.getRange, a.getInfo.getStaticParams)
    }

    /* The Meet Rule's closed-trait case, for functions and functional methods: the
     * declarations whose domains are below both domains together hold every value of
     * their overlap, as the comprises clauses show (OverloadingOracle.coversOverlap).
     * For functional methods of a trait or object that provides them, the overlap is
     * read without the self parameter, as meetRule reads the meet. */
    private def coverageRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                             second: (ArrowType,Option[Int],Option[JavaFunctional]),
                             signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                             isMethod: Boolean,
                             oa: OverloadingOracle): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      if (fsp != gsp || (isMethod && fsp.isEmpty)) false
      else {
        val hs = signatures.collect {
          case (ha, hsp, _) if hsp == fsp && !(ha eq fa) && !(ha eq ga) &&
                               oa.lteq(ha, fa) && oa.lteq(ha, ga) => ha }
        if (isMethod) {
          val i = fsp.get
          oa.coversOverlap(withoutSelf(fa, i), withoutSelf(ga, i), hs.map(withoutSelf(_, i)))
        }
        else oa.coversOverlap(fa, ga, hs)
      }
    }

    /* The return types of a declaration o and of a declaration p that it keeps the type
     * declaring it from inheriting (STypesUtil.providedAndOverridden). Where their parameter
     * types are the same, the two are checked as the pair of an overloading was, o being the
     * more specific, two getters among them (overloading.tex, "Declarations with Static
     * Parameters", the Return Type Rule); where o has the modifier override and widens p's,
     * o's return type must be a subtype of p's (traits.tex, "Method Declarations"): with static
     * parameters, at every instance of p, and where both declare as many of their own, also
     * position by position. */
    private def checkOverridingReturnType(name: IdOrOpOrAnonymousName,
                                          o: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          p: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          equal: Boolean,
                                          oracle: OverloadingOracle): Unit = {
      val getters = isGetter(o._1) && isGetter(p._1)
      def arrow(d: (JavaFunctional, StaticTypeReplacer, TraitType)) =
        if (isFunctionalMethod(d._1)) toFunctionalMethodArrows(Set(d), oracle).headOption
        else if (getters) getterArrow(d)
        else toMethodArrows(Set(d)).headOption
      (arrow(o), arrow(p)) match {
        case (Some(oa), Some(pa)) =>
          if (equal) {
            returnTypeCheck(name, oa, pa, oracle)
            returnTypeCheck(name, pa, oa, oracle)
          } else {
            def own(a: ArrowType) = toListFromImmutable(a.getInfo.getStaticParams).filter(!_.isLifted)
            // the self parameter, or a dotted method's receiver, apart
            val at = oa._2.getOrElse(0)
            val holds =
              if (own(oa._1).isEmpty && own(pa._1).isEmpty)
                isTrue(typeAnalyzer.subtype(oa._1.getRange, pa._1.getRange))(typeAnalyzer)
              else oracle.sa.subtypeUA(withoutSelf(oa._1, at), withoutSelf(pa._1, at)) &&
                   oracle.satisfiesPositionalRule(oa._1, pa._1)
            if (!holds)
              error(mergeSpan(oa._1, pa._1),
                    "For " + name + ",\nthe return type of the overriding declaration " + typeAndSpanToString(oa._1) +
                    " should be a subtype of the\n    return type of the declaration it overrides " + typeAndSpanToString(pa._1))
          }
        case _ =>
      }
    }

    /* Each declaration with the modifier override that the trait or object tt declares must
     * override some inherited declaration: one of its name and kind, with self at the same
     * position, whose parameter types without self are strictly below its own, the pairs that
     * keep tt's walk from inheriting (STypesUtil.providedAndOverridden). It is a static error
     * if it overrides none, so also where the parameter types are equal (traits.tex, "Method
     * Declarations"). A declaration whose own parameter types, or those of an inherited

        // Overloading checking for imported functionals that are not declared in this component
        for ( f <- importNames ) {
          for ( g <- toListFromImmutable(f.getAliasedNames);
                if (g.getAlias.isSome && ! toSet(functions).contains(g.getAlias.unwrap)) ||
                   ! toSet(functions).contains(g.getName) ) {
            val name = if (g.getAlias.isSome) g.getAlias.unwrap.asInstanceOf[IdOrOp].getText
                       else g.getName.asInstanceOf[IdOrOp].getText
            var set = getFunctions(globalEnv.lookup(f.getApiName), g.getName)
            for ( i <- importNames ; if ! f.getApiName.getText.equals(i.getApiName.getText)) {
              for ( n <- toListFromImmutable(i.getAliasedNames) ) {
                if ( n.getAlias.isSome &&
                     n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), n.getName)
                } else if ( n.getAlias.isNone &&
                            n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), g.getName)
                }
              }
            }
            for ( i <- importStars ) {
              val index = globalEnv.lookup(i.getApiName)
              // get the JavaFunctionals from the api and add them to set
              if ( importsOnDemand(index, i, name) ) set ++= getFunctions(index, g.getName)
            }
            checkFunctionOverloading(kindAndName, g.getName, set, globalOracle)
          }
        }

        // All inherited abstract methods in objects should have implementations.
        if ( compilation_unit.isInstanceOf[ComponentIndex] )
          errors = errors ::: new AbstractMethodChecker(compilation_unit.asInstanceOf[ComponentIndex],
                                                        globalEnv).check()

        // Now check trait and object declarations.
        val typesInComp = compilation_unit.typeConses
        for ( t <- toSet(typesInComp.keySet) ; if NU.isTraitOrObject(typesInComp.get(t)) ) {
            val traitOrObject = typesInComp.get(t).asInstanceOf[TraitIndex]
            val traitKindAndName = (traitOrObject match { case _:ObjectTraitIndex => "object "; case _ => "trait " }) + NU.getName(traitOrObject.ast)
            // Extend the type analyzer with the collected static parameters
            val oldTypeAnalyzer = typeAnalyzer
            // Add static parameters of the enclosing trait or object
            typeAnalyzer = typeAnalyzer.extend(toListFromImmutable(traitOrObject.staticParameters),
                                               None)
            staticParamsInScope = toListFromImmutable(traitOrObject.staticParameters)
            val oracle = new OverloadingOracle()(typeAnalyzer)
            /* The parameter type of a setter must be the same as the return type
             * of a getter with the same name, if any.
             */
            for ( f <- toSet(traitOrObject.setters.keySet) ) {
                if ( traitOrObject.getters.keySet.contains(f) ) {
                    val getter = traitOrObject.getters.get(f)
                    // Setter declarations are guaranteed to have a single parameter.
                    val param = traitOrObject.setters.get(f).parameters.get(0)
                    val span = getter.getSpan
                    if ( param.getIdType.isSome ) {
                        if (! isTrue(typeAnalyzer.equivalent(NU.optTypeOrPatternToType(param.getIdType).unwrap,
                                                      getter.getReturnType.unwrap))(typeAnalyzer) )
                            error(span,
                                  "The parameter type of a setter must be " +
                                  "the same as\n    the return type of a getter " +
                                  "with the same name, if any.")
                    }
                }
            }

            val tt = STypesUtil.declToTraitType(traitOrObject.ast)
	        // the methods the trait or object provides, by the traits chapter's inheritance
	        val methods = allMethods(tt, typeAnalyzer)
	        val (methodsR, overridden) = providedAndOverridden(tt, methods, typeAnalyzer, paramsWithoutSelf)

	        for (f <- toSet(methodsR.firstSet) ; if isCheckedName(f) ) {
                  val mset = toSet(methodsR.matchFirst(f))
	              val dottedMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaMethod] &&
	      	      		  		     	     	      m.asInstanceOf[JavaMethod].selfType.isSome })  // unsure why this second condition
	              checkMethodOverloading(traitKindAndName, f, toMethodArrows(dottedMethods), oracle)
	              val functionalMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaFunction]})
	              checkMethodOverloading(traitKindAndName, f, toFunctionalMethodArrows(functionalMethods, oracle), oracle)
	        }
	        // a declaration and one it keeps from being inherited: their return types
	        for ((f, o, p, equal) <- overridden ; if isCheckedName(f))
	          checkOverridingReturnType(f, o, p, equal, oracle)
	        checkOverridesSomething(traitKindAndName, tt, methods, overridden, oracle)
            typeAnalyzer = oldTypeAnalyzer
            staticParamsInScope = Nil
        }
        toJavaList(errors)
    }

    private def checkFancyRule(name: IdOrOpOrAnonymousName,
    	    		       dFunctions: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       fMethods: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       oracle: OverloadingOracle) = {
      // These variables are used to improve the error message
      var x: ArrowType = null 
      var y: ArrowType = null  
      if (!dFunctions.forall(f => fMethods.forall( m => if (!(oracle.lteq(f._1,m._1))) true else { x = f._1; y = m._1; false } )))
        error(x.getInfo().getSpan(),"Overload violation: the declaration of top-level function " + name + " on line " + 
             x.getInfo().getSpan() + " is more specific than the declaration of the functional method " + name + " on line " + 
             y.getInfo().getSpan())
    }

    /* Checks the validity of the overloaded method declarations. */
    private def checkMethodOverloading(containingKindAndName: String,
    	    			       name: IdOrOpOrAnonymousName,
                                       triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				       oracle: OverloadingOracle)
                                      : Unit =
      checkOverloading(containingKindAndName, name, triples, true, oracle)

    /* Checks the validity of the overloaded function declarations. */
    private def checkFunctionOverloading(containingKindAndName: String,
    	    			         name: IdOrOpOrAnonymousName,
                                         triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
					 oracle: OverloadingOracle)
                                        : Unit =
      checkOverloading(containingKindAndName, name, triples, false, oracle)

    /* Checks the validity of the overloaded function declarations. */
