                                	      val mismatch = if (firstO < secondO) firstO + "\n and " + secondO
                                				         else secondO + "\n and " + firstO
                                					      	error(mergeSpan(fa, ga),
                                								"Invalid overloading of " + name + " in " + containingKindAndName +
                                								":\n     " + mismatch)
                                       } else {
                                	      returnTypeCheck(name, first, second, oracle)
